def parse_list(self, response):
    items = response.css('ul li')
    for item in items:
        detail_relative_url = item.css('a::attr(href)').get()
        if detail_relative_url and detail_relative_url.startswith('/adaptive-optics'):
            detail_url = response.urljoin(detail_relative_url)
            yield scrapy.Request(detail_url, callback=self.parse_detail)

